module tb_TopModule;
    logic       clk;
    logic       areset;
    logic       load;
    logic       ena;
    logic [3:0] data;
    logic [3:0] q;

    TopModule uut (
        .clk(clk),
        .areset(areset),
        .load(load),
        .ena(ena),
        .data(data),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        areset = 0;
        load = 0;
        ena = 0;
        data = 4'h0;

        // Test 1: Asynchronous reset
        #2;
        areset = 1;
        #3;
        if (q !== 4'h0) begin
            $display("SELFTEST FAIL: Asynchronous reset failed, q = %h", q);
            $finish;
        end
        areset = 0;
        #5;

        // Test 2: Load data
        data = 4'b1011;
        load = 1;
        ena = 0;
        @(posedge clk);
        #1;
        if (q !== 4'b1011) begin
            $display("SELFTEST FAIL: Load failed, q = %h", q);
            $finish;
        end
        load = 0;

        // Test 3: Enable shift right
        ena = 1;
        @(posedge clk);
        #1;
        // 4'b1011 right shift -> 4'b0101
        if (q !== 4'b0101) begin
            $display("SELFTEST FAIL: Shift right 1 failed, q = %h", q);
            $finish;
        end

        @(posedge clk);
        #1;
        // 4'b0101 right shift -> 4'b0010
        if (q !== 4'b0010) begin
            $display("SELFTEST FAIL: Shift right 2 failed, q = %h", q);
            $finish;
        end

        ena = 0;

        // Test 4: Hold state (neither load nor ena)
        @(posedge clk);
        #1;
        if (q !== 4'b0010) begin
            $display("SELFTEST FAIL: Hold failed, q = %h", q);
            $finish;
        end

        // Test 5: Load priority over ena
        data = 4'b1100;
        load = 1;
        ena = 1;
        @(posedge clk);
        #1;
        if (q !== 4'b1100) begin
            $display("SELFTEST FAIL: Load priority failed, q = %h", q);
            $finish;
        end
        load = 0;
        ena = 0;

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
